<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppIcon from './AppIcon.vue'
import { account, signOut } from '@/lib/account'
import { refresh, workspace } from '@/lib/workspace'
import { describeError } from '@/lib/domain'
const route = useRoute(), router = useRouter(), menu = ref(false), logoutError = ref('')
const page = computed(() => String(route.meta.title || 'Projects'))
const now = computed(() => new Intl.DateTimeFormat('en-US', { dateStyle: 'full', timeZone: workspace.data?.settings.timezone || 'UTC' }).format(new Date()))
watch(() => route.path, () => { menu.value = false; workspace.notice = '' })
async function logout() { try { await signOut(); await router.replace('/auth/signin') } catch (e) { logoutError.value = describeError(e) } }
</script>
<template><a href="#main" class="skip">Skip to content</a><div class="mobilebar"><div class="wordmark"><span class="mark" aria-hidden="true">L</span>Lancealot</div><button aria-controls="workspace-nav" :aria-expanded="menu" @click="menu = !menu">Menu</button></div><aside class="sidebar" :class="{open:menu}"><div class="wordmark"><span class="mark" aria-hidden="true">L</span>Lancealot</div><nav id="workspace-nav" class="side-nav" aria-label="Main navigation"><RouterLink v-for="item in [{path:'/today',label:'Today',icon:'today'},{path:'/clients',label:'Clients',icon:'clients'},{path:'/projects',label:'Projects',icon:'projects'},{path:'/settings',label:'Settings',icon:'settings'}]" :key="item.path" :to="item.path" :class="{'router-link-active': item.path === '/projects' && route.path.startsWith('/projects/')}"><AppIcon :name="item.icon" />{{ item.label }}<span v-if="item.icon === 'today'" class="nav-count">{{ workspace.attention.length }}</span></RouterLink></nav><div class="account">{{ account.sample ? 'Alex Morgan' : account.user?.email }}<small>{{ account.sample ? 'Sample workspace' : 'Private workspace' }}</small><button class="quiet" @click="logout">{{ account.sample ? 'Leave sample' : 'Sign out' }}</button><p v-if="logoutError" class="error-text" role="alert">{{ logoutError }}</p></div></aside><main id="main" class="workspace-main" tabindex="-1"><div class="topline"><span>Your workspace / {{ page }}</span><span>{{ now }}</span></div><div v-if="account.sample" class="notice sample"><span><strong>Sample workspace.</strong> Explore with fictional records. Changes reset when you leave or reload.</span><button class="quiet small" @click="logout">Leave sample</button></div><div v-if="workspace.problem" class="notice error" role="alert">{{ workspace.problem }}<span v-if="workspace.stale"> Showing previously loaded records.</span><button class="small" :disabled="workspace.loading" @click="refresh">Try again</button></div><div v-if="workspace.notice" class="notice success" role="status">{{ workspace.notice }}</div><div v-if="workspace.loading && !workspace.data" role="status"><p class="secondary">Loading your private workspace…</p><div class="skeleton" /><div class="skeleton" /></div><RouterView v-else-if="workspace.data" :key="(account.sample ? 'sample' : account.user?.id)" /></main></template>
